[
  {
    "incident": {
      "component": "MongoDB (mongo-prod-01)",
      "category": "Disk Space Exhaustion",
      "status": "firing",
      "summary": "The primary MongoDB node in production is running out of disk space on /var/lib/mongodb with only 6GiB remaining."
    },
    "assessment": {
      "urgency": "critical",
      "rationale": "The disk is at ~98.5% capacity and the growth rate is 3GiB/h, meaning the disk will be completely full in approximately 2 hours, which will cause the primary to crash and potentially lead to data corruption or replica set instability."
    },
    "facts": [
      "Alert name: MongoDBDiskSpaceLow",
      "Instance: mongo-prod-01:9216",
      "Environment: prod",
      "Filesystem: /var/lib/mongodb",
      "Total size: 400GiB",
      "Available space: 6GiB",
      "Growth rate: 3GiB/h",
      "Replica set role: primary"
    ],
    "missing_context": [
      {
        "item": "Current disk usage breakdown",
        "why": "To identify if the growth is due to data files, journal files, or logs",
        "how_to_check": "df -h /var/lib/mongodb && du -sh /var/lib/mongodb/*"
      },
      {
        "item": "Recent database operations",
        "why": "To determine if a massive write operation or index build is causing the spike",
        "how_to_check": "mongostat --discover"
      }
    ],
    "immediate_actions": [
      {
        "action": "Expand disk volume",
        "purpose": "Provide immediate headroom to prevent service outage",
        "conditions": "If cloud/storage provider allows online expansion",
        "expected_effect": "Increased available space on /var/lib/mongodb",
        "risks": "Potential filesystem locking depending on the underlying storage type",
        "requires_approval": true,
        "verify": "df -h /var/lib/mongodb",
        "rule_ids": [
          "DISK_EXPANSION_01"
        ]
      },
      {
        "action": "Check and rotate logs",
        "purpose": "Free up space if logs are the culprit",
        "conditions": "If du -sh shows large log files",
        "expected_effect": "Immediate reclamation of space",
        "risks": "Loss of recent log history if not handled via rotation",
        "requires_approval": false,
        "verify": "df -h /var/lib/mongodb",
        "rule_ids": [
          "LOG_MANAGEMENT_01"
        ]
      }
    ],
    "investigation_steps": [
      {
        "step": "Analyze disk usage by directory",
        "hypothesis": "The growth is driven by data files (collections/indexes) rather than logs or temp files.",
        "how_to_check": "du -ah /var/lib/mongodb | sort -rh | head -n 20"
      },
      {
        "step": "Check MongoDB OpLog size",
        "hypothesis": "The OpLog is growing unexpectedly due to high write volume.",
        "how_to_check": "db.getReplicationInfo()"
      }
    ],
    "root_cause_hypotheses": [
      "Unexpected surge in write traffic/data ingestion",
      "Unbounded growth of MongoDB logs",
      "Large index builds consuming temporary space",
      "OpLog size configuration is too large for current disk capacity"
    ],
    "dangerous_operations": [
      {
        "operation": "Deleting data files manually",
        "why_dangerous": "Will cause immediate database corruption and crash the instance",
        "rule_id": "DATA_INTEGRITY_01"
      },
      {
        "operation": "Running 'db.dropDatabase()'",
        "why_dangerous": "Permanent loss of production data",
        "rule_id": "DATA_LOSS_PREVENTION"
      }
    ],
    "applied_expert_rules": [
      "DISK_EXPANSION_01",
      "LOG_MANAGEMENT_01",
      "DATA_INTEGRITY_01"
    ],
    "incident_update": "🚨 *CRITICAL*: `mongo-prod-01` (Primary) is running out of disk space on `/var/lib/mongodb`. Current available: 6GiB. Growth rate: 3GiB/h. Estimated time to exhaustion: ~2 hours. Investigating disk usage and preparing for volume expansion."
  }
]
